import { goalOptions, labels } from "../data/demo-data.js";
import { metricSections, metricDefinitions } from "../data/fitmao-metrics.js";
import { glossaryData, glossaryEntry } from "../data/glossary-data.js";
import { rankingNotice } from "../data/ranking-rules.js";
import { rankFocusAreas } from "../services/ranking-service.js";
import { explainFocus } from "../services/explanation-service.js";
import { compareAssessments } from "../services/comparison-service.js";
import { escapeHtml, label, formatDate, pageHeader, notice, professionalNotice, emptyState } from "../components/ui.js";
import { focusCard } from "../components/focus-card.js";
import { metricRow } from "../components/metric-row.js";

const latest=state=>state.assessments.at(-1);
const ranking=state=>state.latestResult?.ranking||rankFocusAreas(latest(state),state.profile);
const sourceNotice=()=>notice("QR reading, screenshot text extraction, account access, and cloud saving are simulated. You must verify every captured value.","info","What is simulated");
const stepper=(active,items=["Profile","Assessment","Results"])=>`<ol class="stepper" aria-label="Progress">${items.map((item,index)=>`<li class="${index+1===active?"is-active":index+1<active?"is-done":""}"><span>${index+1<active?"✓":index+1}</span><small>${item}</small></li>`).join("")}</ol>`;
const goalCards=(name,current)=>goalOptions.map(([value,title,help])=>`<label class="choice-card"><input type="radio" name="${name}" value="${value}" ${current===value?"checked":""}><span><strong>${title}</strong><small>${help}</small></span></label>`).join("");
const selectOptions=(values,current)=>values.map(value=>`<option value="${value}" ${current===value?"selected":""}>${labels[value]}</option>`).join("");
const valueText=m=>`${escapeHtml(m.value)}${m.unit&&m.unit!=="—"?` ${escapeHtml(m.unit)}`:""}`;

export function welcomeView(){return `<main class="welcome" id="main-content"><header class="welcome-nav"><a class="brand" href="#/welcome"><span class="brand-mark">FS</span><span>FITSTART</span></a><a class="text-button" href="#/sign-in">Sign In</a></header><section class="hero"><div class="hero-copy"><p class="eyebrow">For new KSYN Fitness Alabang members</p><h1>Understand your assessment.<br><em>Start with what matters to you.</em></h1><p class="lead">FITSTART organizes a FitMao body-composition report into a clear starting point based on your confirmed results and fitness goal.</p><div class="hero-actions"><a class="button button-primary button-large" href="#/sign-in">Create My Profile</a><button class="button button-secondary button-large" data-action="explore-demo">Explore Demo</button></div><button class="text-button" data-action="open-boundaries">What FITSTART does and does not do</button></div><div class="hero-panel"><p class="eyebrow">A simpler way to begin</p><ol class="welcome-steps"><li><span>1</span><div><strong>Add Report</strong><small>Use a QR code, screenshot, or manual entry.</small></div></li><li><span>2</span><div><strong>Confirm Your Context</strong><small>Tell us your goal and experience.</small></div></li><li><span>3</span><div><strong>Understand Your Focus</strong><small>See what report information to review first.</small></div></li></ol></div></section><footer class="welcome-foot"><strong>Educational-use prototype</strong><p>FITSTART does not diagnose, prescribe workouts or diets, or replace a qualified fitness professional.</p></footer></main>`}

export function authView(){return `<main class="auth-page" id="main-content"><a class="brand" href="#/welcome"><span class="brand-mark">FS</span><span>FITSTART</span></a><section class="auth-card"><a class="back-link" href="#/welcome">← Back</a><p class="eyebrow">Simulated account access</p><h1 tabindex="-1">Create your member profile</h1><p>This test does not connect to Google or send email. Your entries stay in this browser.</p><div class="auth-tabs" role="tablist"><button class="is-active" data-auth-tab="create" role="tab" aria-selected="true">Create Account</button><button data-auth-tab="signin" role="tab" aria-selected="false">Sign In</button></div><button class="button button-google" data-action="google-signin">G <span>Continue with Google</span></button><div class="divider"><span>or use email</span></div><form id="auth-form"><div class="field"><label for="email">Email address</label><input class="input" id="email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="password">Password</label><input class="input" id="password" name="password" type="password" minlength="6" autocomplete="new-password" required><small>Use at least 6 characters for this simulated account.</small></div><p class="field-error" data-error="auth" aria-live="polite"></p><button class="button button-primary button-block" type="submit">Continue</button></form><button class="text-button" data-action="forgot-password">Forgot password?</button><p class="fine-print">Prototype only: no real account is created and no information leaves this browser.</p></section></main>`}

export function onboardingView(state){const p=state.profile||{},step=state.ui.onboardingStep||1;const body={1:`<div class="field"><label for="displayName">What should we call you?</label><input class="input" id="displayName" name="displayName" value="${escapeHtml(p.displayName||"")}" autocomplete="name" required><small>A first name or nickname is enough.</small></div>`,2:`<fieldset><legend>What is your main fitness goal?</legend><p class="field-help">Your goal helps FITSTART decide which report information is most relevant.</p><div class="choice-grid">${goalCards("primaryGoal",p.primaryGoal)}</div></fieldset><div class="field"><label for="secondaryGoal">Optional second goal</label><select class="select" id="secondaryGoal" name="secondaryGoal"><option value="">No second goal</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div>`,3:`<fieldset><legend>How much fitness-assessment experience do you have?</legend><p class="field-help">This changes how much explanation we show, not your ranking.</p><div class="choice-grid compact">${["new","somewhat-experienced","experienced"].map(v=>`<label class="choice-card"><input type="radio" name="fitnessExperience" value="${v}" ${p.fitnessExperience===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset>`,4:`<fieldset><legend>How familiar are you with body-composition terms?</legend><p class="field-help">We use this only to choose clearer or more concise explanations.</p><div class="choice-grid compact">${["not-familiar","somewhat-familiar","very-familiar"].map(v=>`<label class="choice-card"><input type="radio" name="assessmentFamiliarity" value="${v}" ${p.assessmentFamiliarity===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset>`}[step];return `<main class="page narrow" id="main-content">${stepper(1,["Your name","Your goals","Experience","Familiarity"])}<section class="card onboarding-card"><p class="eyebrow">Profile setup · Step ${step} of 4</p><h1 tabindex="-1">${["Let’s start with your name","What would you like to focus on?","Help us match the explanation to you","One last question"][step-1]}</h1><form id="onboarding-form" data-step="${step}">${body}<p class="field-error" data-error="onboarding" aria-live="polite"></p><div class="button-row spread">${step>1?'<button class="button button-secondary" type="button" data-action="onboarding-back">Back</button>':'<a class="button button-secondary" href="#/sign-in">Back</a>'}<button class="button button-primary" type="submit">${step===4?"Save Profile":"Continue"}</button></div></form></section></main>`}

export function dashboardView(state){const assessment=latest(state),result=ranking(state),main=result.mainFocus;return `<div class="page">${pageHeader("Member home",`Welcome, ${state.profile?.displayName||"Member"}`,assessment?"Your latest assessment is ready to review.":"Add your first FitMao report to get a clear starting point.",`<a class="button button-primary" href="#/assessment/add">${assessment?"Add New Assessment":"Add FitMao Assessment"}</a>`)}<section class="goal-strip"><div><small>Your main goal</small><strong>${label(state.profile?.primaryGoal)}</strong></div><a href="#/profile">Edit profile</a></section>${!assessment?`<section class="card empty-state large"><span class="empty-icon">▤</span><h2>No assessment yet</h2><p>When you add a report, you will check every captured value before FITSTART organizes it.</p><a class="button button-primary button-large" href="#/assessment/add">Add My First Assessment</a></section>`:`<section class="dashboard-focus"><div><p class="eyebrow">Your Main Focus</p><h2>${escapeHtml(main?.label||"No clear focus found")}</h2><p>${escapeHtml(main?.definition||"Review the complete results with a qualified fitness professional.")}</p><p class="supporting">Latest assessment · ${formatDate(assessment.assessedAt)}</p><a class="button button-light" href="#/results">View Personalized Results</a></div><div class="focus-number"><span>#1</span><small>information to review first</small></div></section>`}<section class="quick-grid"><a class="card quick-card" href="#/glossary"><span>?</span><div><strong>Glossary</strong><small>Look up an unfamiliar report term.</small></div></a>${assessment?`<a class="card quick-card" href="#/report"><span>▤</span><div><strong>Full FitMao Report</strong><small>See every confirmed source value.</small></div></a>`:""}<a class="card quick-card ${state.assessments.length<2?"is-locked":""}" href="${state.assessments.length<2?"#/dashboard":"#/compare"}" ${state.assessments.length<2?'aria-disabled="true" title="Add a second confirmed assessment to compare"':""}><span>↔</span><div><strong>Compare</strong><small>${state.assessments.length<2?"Available after two confirmed reports.":"Compare your two newest reports."}</small></div></a></section></div>`}

export function assessmentAddView(){return `<div class="page">${pageHeader("Add assessment","How would you like to add your FitMao report?","No matter which option you choose, you will review the captured values before they are used.")}<div class="source-grid"><article class="source-card recommended"><span class="pill">Recommended</span><span class="source-icon">▣</span><h2>Upload Report Screenshot</h2><p>Choose a clear image. This prototype previews it and prefills fictional values for review.</p><label class="button button-primary" for="report-upload">Choose Screenshot</label><input class="visually-hidden" id="report-upload" type="file" accept="image/*"><button class="text-button" data-action="use-upload" disabled>Continue with selected image</button></article><article class="source-card"><span class="source-icon">⌗</span><h2>Scan FitMao QR</h2><p>Use the simulated QR reader, then verify all imported values.</p><button class="button button-secondary" data-action="use-qr">Open QR Preview</button></article><article class="source-card"><span class="source-icon">⌨</span><h2>Enter Values Manually</h2><p>Type the values printed on a FitMao report section by section.</p><a class="button button-secondary" href="#/assessment/manual">Enter Report Values</a></article></div>${sourceNotice()}</div>`}

export function manualEntryView(state){const assessment=state.draftAssessment;return `<div class="page">${pageHeader("Manual report entry","Enter the values printed on your FitMao report","You can leave optional values unavailable. Required values are marked.")}<form id="manual-form"><div class="report-sections">${metricSections.map(section=>`<details class="card report-section" open><summary><strong>${section}</strong><span>${metricDefinitions.filter(m=>m.section===section).length} fields</span></summary><div class="manual-grid">${metricDefinitions.filter(m=>m.section===section).map((m,index)=>`<div class="field"><label for="manual-${m.id}">${m.name}${["weight","pbf","smm"].includes(m.id)?" *":""}</label><div class="input-with-unit"><input class="input" id="manual-${m.id}" name="${m.id}" ${typeof (assessment?.metrics.find(x=>x.id===m.id)?.value) === "number"?"type=number step=any":"type=text"} value="${escapeHtml(assessment?.metrics.find(x=>x.id===m.id)?.value??"")}"><span>${m.unit}</span></div><small>${m.range}</small></div>`).join("")}</div></details>`).join("")}</div><p class="field-error" data-error="manual" aria-live="polite"></p><div class="sticky-action"><button class="button button-secondary" type="button" data-action="save-manual">Save Draft</button><button class="button button-primary" type="submit">Continue to Review</button></div></form></div>`}

export function assessmentReviewView(state){const a=state.draftAssessment;if(!a)return `<div class="page">${emptyState("Nothing to review","Choose an assessment method first.","#/assessment/add","Add assessment")}</div>`;return `<div class="page wide">${pageHeader("Review and verify","Check the captured values against your FitMao report","Original FitMao ranges and positions are shown exactly as captured.")}<div class="review-layout"><aside class="report-preview"><img src="${escapeHtml(a.previewUrl||"assets/images/demo-fitmao-report.svg")}" alt="Preview of the report being reviewed"><p>${escapeHtml(a.fileName||"Simulated FitMao report preview")}</p></aside><form id="review-form" class="metric-editor"><div class="review-list">${a.metrics.map(m=>`<div class="edit-row"><div><label for="metric-${m.id}">${m.name}</label><small>Printed reference: ${m.range}</small></div><div class="input-with-unit"><input class="input" id="metric-${m.id}" name="metric-${m.id}" value="${escapeHtml(m.value)}" ${typeof m.value==="number"?'type="number" step="any"':'type="text"'}><span>${m.unit}</span></div><div class="field"><label class="visually-hidden" for="status-${m.id}">Original report position for ${m.name}</label><select class="select" id="status-${m.id}" name="status-${m.id}">${["Under","Normal","Over","Not provided","Report output","Original label"].map(v=>`<option ${m.status===v?"selected":""}>${v}</option>`).join("")}</select></div></div>`).join("")}</div><label class="confirm-box"><input type="checkbox" name="reviewed"><span><strong>I reviewed these values and they match my FitMao report.</strong><small>FITSTART will only rank information after this confirmation.</small></span></label><p class="field-error" data-error="review" aria-live="polite"></p><div class="sticky-action"><a class="button button-secondary" href="#/assessment/add">Back</a><button class="button button-primary" type="submit">Confirm Assessment</button></div></form></div></div>`}

export function contextView(state){const p=state.profile;return `<div class="page narrow">${stepper(2)}${pageHeader("Confirm your context","Is this information still correct?","FITSTART uses your goals to rank focus areas and your experience only to adjust explanation depth.")}<section class="summary-cards"><div><small>Primary goal</small><strong>${label(p.primaryGoal)}</strong></div><div><small>Secondary goal</small><strong>${p.secondaryGoal?label(p.secondaryGoal):"None selected"}</strong></div><div><small>Fitness experience</small><strong>${label(p.fitnessExperience)}</strong></div><div><small>Assessment terms</small><strong>${label(p.assessmentFamiliarity)}</strong></div></section><details class="card context-editor"><summary>Edit this information</summary><form id="context-form"><div class="field"><label for="context-primary">Primary goal</label><select class="select" id="context-primary" name="primaryGoal">${goalOptions.map(([v,t])=>`<option value="${v}" ${p.primaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label for="context-secondary">Secondary goal</label><select class="select" id="context-secondary" name="secondaryGoal"><option value="">None</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><button class="button button-secondary" type="submit">Save Context</button></form></details><div class="button-row spread"><button class="button button-secondary" data-action="edit-latest-assessment">Edit Assessment</button><button class="button button-primary button-large" data-action="generate-results">Use This Context</button></div></div>`}

export function processingView(){return `<div class="page processing-page"><div class="processing-mark">FS</div><p class="eyebrow">Preparing your starting point</p><h1 tabindex="-1">Organizing your confirmed report</h1><ol class="processing-list">${["Checking confirmed FitMao values","Grouping related measurements","Matching focus areas with your goal","Ranking relevant focus areas","Preparing plain-language explanations"].map((text,i)=>`<li data-process="${i}"><span></span>${text}</li>`).join("")}</ol><p>FITSTART uses fixed demonstration rules. It is not diagnosing or predicting anything.</p></div>`}

export function resultsView(state){const a=latest(state),r=ranking(state);if(!a)return `<div class="page">${emptyState("No results yet","Add and confirm a FitMao assessment first.","#/assessment/add","Add assessment")}</div>`;if(r.insufficient)return `<div class="page">${pageHeader("Personalized Starting Point","No single focus area clearly stands out","FITSTART could not identify one assessment area that clearly deserves greater attention from the available report.")}${professionalNotice()}</div>`;const main=r.mainFocus,e=explainFocus(main,state.profile);return `<div class="page results-page">${pageHeader("Personalized Starting Point","Start with the information that matters most","Assessment from "+formatDate(a.assessedAt))}${notice("This educational prototype organizes confirmed report information. It does not provide a medical conclusion or personal workout or diet plan.","info","Educational use only")}<article class="main-focus-card"><div><span class="pill light">Main Focus · Rank 1</span><p class="eyebrow">Review this first</p><h2>${main.label}</h2><p class="lead">${e.definition}</p><div class="evidence-chips">${main.supporting.slice(0,3).map(m=>`<span><strong>${m.name}</strong>${valueText(m)} · ${m.status}</span>`).join("")}</div><a class="button button-light" href="#/results/focus/${main.id}">See Full Explanation</a></div><div class="rank-orb"><strong>1</strong><span>of ${r.items.length}</span></div></article><section class="card why-card"><p class="eyebrow">Why this ranked first</p><div class="why-grid"><div><span>◎</span><strong>You told us</strong><p>${e.toldUs}</p></div><div><span>▤</span><strong>Your report shows</strong><p>${e.showed}</p></div></div><p class="why-summary">${e.why}</p></section><section class="section"><div class="section-head"><div><p class="eyebrow">Ranked Priorities</p><h2>Other information to review</h2></div></div><div class="focus-list">${r.priorities.map((f,i)=>focusCard(f,i+2)).join("")}</div></section>${professionalNotice()}<section class="result-actions"><a class="button button-secondary" href="#/summary">Open Trainer Discussion Summary</a><a class="button button-secondary" href="#/report">View Complete FitMao Report</a><a class="button button-secondary" href="#/glossary">Open Glossary</a></section></div>`}

export function focusDetailView(state,id){const r=ranking(state),focus=r.items.find(item=>item.id===id);if(!focus)return `<div class="page">${emptyState("Focus area not found","Return to your personalized results.","#/results","Back to results")}</div>`;const e=explainFocus(focus,state.profile),rank=r.items.findIndex(item=>item.id===id)+1;return `<div class="page"><nav class="breadcrumbs"><a href="#/results">Results</a><span>/</span><span>${focus.label}</span></nav>${pageHeader(`Rank ${rank}`,focus.label,e.definition)}<div class="detail-grid"><div class="stack"><section class="card explanation-stack"><div><span>1</span><div><h2>You Told Us</h2><p>${e.toldUs}</p></div></div><div><span>2</span><div><h2>Your FitMao Report Shows</h2><p>${e.showed}</p></div></div><div><span>3</span><div><h2>Why This Ranked Here</h2><p>${e.why}</p></div></div></section><section class="card"><h2>Supporting Measurements</h2><p>These results support one focus area; they are not separate priorities.</p><div class="metric-lines">${focus.supporting.map(metricRow).join("")}</div></section><section class="recommendation"><span>→</span><div><h2>What to review first</h2><p>${e.recommendation}</p></div></section></div><aside class="stack">${professionalNotice()}${state.ui.researchMode?`<details class="card research-details"><summary>Research Mode details</summary><p>${rankingNotice}</p><dl><div><dt>Assessment evidence</dt><dd>${focus.evidence}</dd></div><div><dt>Primary-goal relevance</dt><dd>${focus.primary}</dd></div><div><dt>Secondary-goal relevance</dt><dd>${focus.secondary}</dd></div><div><dt>Final focus score</dt><dd>${focus.score}</dd></div></dl></details>`:""}</aside></div></div>`}

export function summaryView(state){const a=latest(state),r=ranking(state);if(!a)return `<div class="page">${emptyState("No summary available","Confirm an assessment first.","#/assessment/add","Add assessment")}</div>`;return `<div class="page print-page">${pageHeader("Trainer Discussion Summary",`${state.profile.displayName}’s review notes`,`Prepared from the confirmed FitMao assessment on ${formatDate(a.assessedAt)}.`,`<button class="button button-secondary" data-action="print-summary">Print Summary</button>`)}<section class="paper"><div class="summary-top"><div><small>Stated goal</small><strong>${label(state.profile.primaryGoal)}</strong></div><div><small>Assessment date</small><strong>${formatDate(a.assessedAt)}</strong></div></div><section><p class="eyebrow">Main Focus</p><h2>${r.mainFocus?.label||"No clear focus"}</h2></section><section><h2>Ranked Priorities</h2><ol>${r.priorities.map(f=>`<li>${f.label}</li>`).join("")||"<li>No additional priorities</li>"}</ol></section><section><h2>Key original FitMao values</h2><div class="metric-lines">${r.mainFocus?.supporting.slice(0,4).map(metricRow).join("")||""}</div></section><section><h2>Questions you may ask a professional</h2><ul><li>Can you explain what these results mean for my goal?</li><li>Which exercise and nutrition strategies are appropriate for me?</li><li>How should I measure future changes consistently?</li></ul></section>${professionalNotice()}</section></div>`}

export function fullReportView(state){const a=latest(state),previous=state.assessments.at(-2);if(!a)return `<div class="page">${emptyState("No confirmed report","Add and confirm an assessment first.","#/assessment/add","Add assessment")}</div>`;return `<div class="page wide">${pageHeader("Complete FitMao Report","Every confirmed source value","FITSTART preserves the report information and does not replace the original source report.")}<div class="report-layout"><aside class="report-sidebar"><img src="assets/images/demo-fitmao-report.svg" alt="Fictional FitMao demonstration report"><nav>${metricSections.map((s,i)=>`<a href="#report-section-${i}">${s}</a>`).join("")}${previous?'<a href="#report-history">Report History</a>':""}</nav></aside><div class="report-content">${a.notice?notice(a.notice,"info","Demonstration data"):""}${metricSections.map((section,i)=>`<section class="card report-table" id="report-section-${i}"><h2>${section}</h2><div class="metric-lines">${a.metrics.filter(m=>m.section===section).map(metricRow).join("")}</div></section>`).join("")}${previous?`<section class="card report-table" id="report-history"><h2>Report History</h2><p>Previous confirmed assessment: ${formatDate(previous.assessedAt)}</p><div class="metric-lines">${previous.metrics.slice(0,8).map(metricRow).join("")}</div></section>`:""}${professionalNotice()}</div></div></div>`}

export function glossaryView(){const categories=[...new Set(glossaryData.map(item=>item.category))];return `<div class="page">${pageHeader("Glossary","Understand the terms on your report","Search for a metric or browse by category. Definitions explain the report without diagnosing you.")}<div class="search-tools"><div class="field"><label for="glossary-search">Search the glossary</label><input class="input" id="glossary-search" type="search" placeholder="Try “body fat” or “BMI”"></div><div class="filters" aria-label="Glossary categories"><button class="is-active" data-glossary-filter="all">All</button>${categories.map(c=>`<button data-glossary-filter="${c}">${c}</button>`).join("")}</div></div><section class="glossary-grid">${glossaryData.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(item=>`<article class="card glossary-card" data-glossary-card data-name="${escapeHtml(`${item.name} ${item.abbr}`.toLowerCase())}" data-category="${item.category}"><span class="pill">${item.category}</span><h2>${item.name}</h2><p>${item.definition}</p><a href="#/glossary/${item.id}">Read definition →</a></article>`).join("")}</section><section id="glossary-empty" class="card empty-state" hidden><h2>No matching term</h2><p>Try a shorter word or choose All.</p></section></div>`}

export function glossaryDetailView(state,id){const item=glossaryEntry(id);if(!item)return `<div class="page">${emptyState("Term not found","Return to the glossary and choose another term.","#/glossary","Open glossary")}</div>`;return `<div class="page narrow"><nav class="breadcrumbs"><a href="#/glossary">Glossary</a><span>/</span><span>${item.name}</span></nav>${pageHeader(item.category,item.name,item.abbr!=="—"?`Also shown as ${item.abbr}.`:"Plain-language definition")}<section class="card definition-hero"><p class="eyebrow">In simple terms</p><h2>${item.definition}</h2></section><section class="card info-sections"><div><h2>What FitMao reports</h2><p>${item.reports}</p></div><div><h2>Keep in mind</h2><p>${item.limitation}</p></div><div><h2>Research source</h2><p>${item.source}</p></div></section>${item.related.length?`<section><h2>Related glossary terms</h2><div class="related-links">${item.related.map(r=>{const m=glossaryEntry(r);return `<a class="card" href="#/glossary/${r}">${m.name} →</a>`}).join("")}</div></section>`:""}</div>`}

export function compareView(state){if(state.assessments.length<2)return `<div class="page">${emptyState("Compare is not available yet","Add and confirm a second FitMao assessment to compare your two newest reports.","#/assessment/add","Add second assessment")}</div>`;const [previous,current]=state.assessments.slice(-2),rows=compareAssessments(previous,current,state.profile.primaryGoal);return `<div class="page">${pageHeader("Limited comparison","Your two newest confirmed reports","This view compares measured values only. It does not prove improvement or failure.")}<div class="date-compare"><div><small>Previous</small><strong>${formatDate(previous.assessedAt)}</strong></div><span>→</span><div><small>Current</small><strong>${formatDate(current.assessedAt)}</strong></div></div><section class="card comparison-table">${rows.map(row=>`<div class="comparison-row"><div><strong>${row.name}</strong><small>${row.changeLabel}</small></div><span>${row.previousValue} ${row.unit}</span><span>→</span><span>${row.currentValue} ${row.unit}</span><strong class="difference">${row.difference>0?"+":""}${row.difference} ${row.unit}</strong><p>${row.supportsGoal?`This movement is in the direction of your stated ${label(state.profile.primaryGoal)} goal.`:"No approved goal-direction statement is shown for this change."}${row.large?" Large difference detected. Verify both FitMao reports before interpreting the change.":""}</p></div>`).join("")}</section>${notice("Measurement conditions may affect body-composition results. Try to compare reports taken under similar conditions.","warning","Measurement variability")}${professionalNotice()}</div>`}

export function profileView(state){const p=state.profile;return `<div class="page">${pageHeader("Profile and settings","Your personal context","Update the information used to organize and explain your report.")}<div class="settings-grid"><form class="card" id="profile-form"><div class="field"><label for="profile-name">Name</label><input class="input" id="profile-name" name="displayName" value="${escapeHtml(p.displayName)}"></div><div class="field"><label for="profile-email">Demo email</label><input class="input" id="profile-email" value="${escapeHtml(p.email||"Saved locally")}" disabled></div><div class="field"><label for="profile-goal">Primary goal</label><select class="select" id="profile-goal" name="primaryGoal">${goalOptions.map(([v,t])=>`<option value="${v}" ${p.primaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label for="profile-secondary">Secondary goal</label><select class="select" id="profile-secondary" name="secondaryGoal"><option value="">None</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label for="profile-experience">Fitness experience</label><select class="select" id="profile-experience" name="fitnessExperience">${selectOptions(["new","somewhat-experienced","experienced"],p.fitnessExperience)}</select></div><div class="field"><label for="profile-familiarity">Assessment familiarity</label><select class="select" id="profile-familiarity" name="assessmentFamiliarity">${selectOptions(["not-familiar","somewhat-familiar","very-familiar"],p.assessmentFamiliarity)}</select></div><p class="field-error" data-error="profile" aria-live="polite"></p><button class="button button-primary" type="submit">Save Profile</button></form><aside class="stack"><section class="card"><h2>Research Mode</h2><p>Show prototype ranking points and research-only comparison tools.</p><label class="toggle"><input type="checkbox" data-action="toggle-research" ${state.ui.researchMode?"checked":""}><span></span>Research Mode ${state.ui.researchMode?"on":"off"}</label>${state.ui.researchMode?'<a class="button button-secondary button-block" href="#/research-comparison">Open Research Comparison</a>':""}</section><section class="card"><h2>More</h2><a class="settings-link" href="#/report">Full FitMao Report <span>→</span></a><a class="settings-link ${state.assessments.length<2?"is-disabled":""}" href="${state.assessments.length<2?"#/profile":"#/compare"}">Compare <span>${state.assessments.length<2?"Locked":"→"}</span></a><button class="settings-link" data-action="sign-out">Sign Out <span>→</span></button></section><section class="card danger-zone"><h2>Local prototype data</h2><p>Your profile and up to two assessments are saved only in this browser.</p><button class="button button-danger" data-action="clear-data">Clear Demo Data</button></section></aside></div></div>`}

export function researchView(state){const a=latest(state),r=ranking(state);if(!state.ui.researchMode)return `<div class="page">${emptyState("Research Mode is off","Turn it on in Profile to view this neutral comparison.","#/profile","Open profile")}</div>`;return `<div class="page wide">${pageHeader("Research Comparison","Original report and FITSTART presentation","Both sides use identical source values. Neither presentation is labeled as better or easier.")}<div class="research-tabs" role="tablist"><button class="is-active" data-research-tab="original">Original FitMao Report</button><button data-research-tab="fitstart">FITSTART Presentation</button></div><div class="research-split"><section data-research-panel="original" class="is-active"><h2>Original FitMao Report</h2><img src="assets/images/demo-fitmao-report.svg" alt="Fictional original FitMao report structure"><div class="metric-lines">${a?.metrics.slice(0,8).map(metricRow).join("")||""}</div></section><section data-research-panel="fitstart"><h2>FITSTART Presentation</h2>${r.mainFocus?focusCard(r.mainFocus,1):"<p>No focus available.</p>"}<div class="focus-list">${r.priorities.map((f,i)=>focusCard(f,i+2)).join("")}</div></section></div><p class="fine-print">${rankingNotice}</p></div>`}

export function notFoundView(){return `<div class="page">${emptyState("We could not find that page","Use the dashboard to continue your FITSTART journey.","#/dashboard","Go to Dashboard")}</div>`}
